parameters.prompt:
=Analyze this transcript and identify the 3-5 most engaging fragments:

Title: {{ $json.body.title }}

Transcript:
{{ $json.body.transcript }}

=Extract the exact verbatim text for these fragments from the transcript:

Fragments to extract:
{{ $('Fragment Selection').item.json.message.content }}

Full transcript:
{{ $('Webhook').item.json.body.transcript }}

Provide the exact text for each fragment, separated by '---'

parameters.jsCode:
const fragmentText = $input.item.json.message.content;

// Split by --- delimiter
const fragments = fragmentText.split('---').filter(f => f.trim());

// Parse each fragment
const parsedFragments = fragments.map((fragment, index) => {
  const trimmed = fragment.trim();

  // Extract timecodes using regex [HH:MM] -- [HH:MM]
  const timecodeMatch = trimmed.match(/\[(\d{2}:\d{2})\]\s*--\s*\[(\d{2}:\d{2})\]/);

  if (!timecodeMatch) {
    return null;
  }

  const start = timecodeMatch[1];
  const end = timecodeMatch[2];

  // Extract content (everything after the timecode line)
  const contentStart = trimmed.indexOf('\n', timecodeMatch.index);
  const content = contentStart !== -1 ? trimmed.substring(contentStart + 1).trim() : '';

  return {
    json: {
      fragmentIndex: index + 1,
      start: start,
      end: end,
      content: content,
      timecodeRange: `${start} -- ${end}`
    }
  };
}).filter(f => f !== null);

return parsedFragments;

parameters.message:
=Please find attached the SRT subtitle file for fragment {{ $json.fragmentIndex }}.

Timecode: {{ $('Split Fragments').item.json.timecodeRange }}

This fragment was selected as one of the most engaging moments from the transcript.
